import{_ as n,o as a,c as i,ag as t}from"./chunks/framework.CrXGS008.js";const p=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"de/repair-station/index.md","filePath":"de/repair-station/index.md"}'),r={name:"de/repair-station/index.md"};function s(o,e,l,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>Man fährt auf eine Repair Station, wählt eine Leistung, und das Fahrzeug wird vor Ort repariert: Motor, Karosserie und Reifen, mit Ton und Funken. Der Preis richtet sich nach dem Schaden, ein zerkratztes Auto zahlt also weniger als ein Wrack. Stationen werden im Spiel platziert und jede Einstellung wird im Spiel bearbeitet.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><ul><li><strong>Drei Leistungen ab Werk</strong>: Schnellreparatur (Motor), Karosseriearbeit (Karosserie und Reifen), Komplettreparatur. Name, Preis, Dauer und reparierte Teile lassen sich ändern. Siehe <a href="/de/repair-station/settings">Einstellungen</a>.</li><li><strong>Preis nach Schaden</strong>: Der Preis folgt dem Schaden der reparierten Teile, bis zu einem Mindestprozentsatz. Unbeschädigte Fahrzeuge werden abgelehnt.</li><li><strong>Stationseditor im Spiel</strong>: Lege eine Station dort an, wo du stehst, verschiebe die Haltezone und ein optionales Prop mit der Tastatur und speichere. Siehe <a href="/de/repair-station/stations">Stationen</a>.</li><li><strong>Mechaniker zuerst</strong>: Stationen schließen, solange genug Mechaniker im Dienst sind, und die Spieler rufen sie.</li><li><strong>Fair und sicher</strong>: ein Fahrzeug pro Station, Prüfung von Fahrer und Geschwindigkeit, Zahlungen vom Server geprüft. Eine abgebrochene Reparatur wird auf das belastete Konto erstattet.</li><li><strong>Job-Rabatte</strong>, ein Preisprozentsatz pro Station und Zahlung per Bargeld, Bank oder Bargeld und dann Bank.</li><li><strong>Alles in <code>/nay</code></strong>: Leistungen, Preise, Stationen, Mechaniker-Jobs, Blips mit visueller Auswahl von Symbol und Farbe.</li><li><strong>HTTP-API und Webhooks</strong>: Reparaturverlauf, Statistiken und Stationen für deine Website oder deinen Bot, eine Discord-Nachricht bei jeder Reparatur. Siehe <a href="/de/repair-station/api">API und Webhooks</a>.</li><li><strong>Erweiterbar</strong>: Eine zweite Ressource kann Preise ändern, Stationen schließen und an jeder Reparatur teilnehmen. Siehe <a href="/de/repair-station/api#extensions">Erweiterungen</a>.</li><li><strong>Sechs Sprachen</strong>: Englisch, Französisch, Spanisch, Portugiesisch, Polnisch, Deutsch.</li></ul><h2 id="kompatibilitat" tabindex="-1">Kompatibilität <a class="header-anchor" href="#kompatibilitat" aria-label="Permalink to &quot;Kompatibilität&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, automatisch erkannt.</li><li>Abhängigkeiten: oxmysql und <code>nay_lib</code> (im Kauf enthalten).</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Alle Schritte stehen auf der Seite <a href="/de/getting-started">Erste Schritte</a>. Gib dir danach <code>nay_repair.config</code> (oder <code>nay.admin</code>) und öffne <code>/nay</code>. Drei Stationen sind ab Werk bereit: Hayes Autos, Sandy Shores und Paleto Bay.</p>`,9)])])}const g=n(r,[["render",s]]);export{p as __pageData,g as default};
